import java.util.*;

/** 業務の判断の結果。HTTPもCLIも知らない。 */
enum OrderResult { OK, EMPTY_ITEM, INVALID_COUNT, OUT_OF_STOCK }

/** 業務ルールだけを持つ。戻り値が OrderResult なので、HTTPのことは書けない。 */
class OrderDomain {
    private final Map<String, Integer> stock = new HashMap<>(Map.of("book", 3, "pen", 1));

    OrderResult check(String item, int count) {
        if (item.isEmpty()) return OrderResult.EMPTY_ITEM;
        if (count < 1 || count > 10) return OrderResult.INVALID_COUNT;
        Integer current = stock.get(item);
        if (current == null || current < count) return OrderResult.OUT_OF_STOCK;
        return OrderResult.OK;
    }
}

/** 業務の判断をHTTPの応答へ翻訳する。ここに業務ルールは書かない。 */
class HttpAdapter {
    String render(OrderResult result) {
        return switch (result) {
            case OK -> "200 OK";
            case EMPTY_ITEM -> "400 INVALID_ITEM";
            case INVALID_COUNT -> "400 INVALID_COUNT";
            case OUT_OF_STOCK -> "409 OUT_OF_STOCK";
        };
    }
}

/** 同じ判断を、画面向けの文へ翻訳する。 */
class CliAdapter {
    String render(OrderResult result) {
        return switch (result) {
            case OK -> "注文を受け付けました";
            case EMPTY_ITEM -> "商品を指定してください";
            case INVALID_COUNT -> "個数は1〜10で指定してください";
            case OUT_OF_STOCK -> "在庫が足りません";
        };
    }
}

public class Main {
    public static void main(String[] a) {
        Scanner sc = new Scanner(System.in);
        String item = sc.next();
        if (item.equals("_")) item = "";
        int count = sc.nextInt();
        OrderResult result = new OrderDomain().check(item, count);
        System.out.println(new HttpAdapter().render(result));
        System.out.println(new CliAdapter().render(result));
    }
}

