import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String[] products = sc.nextLine().trim().split("\\s+");
        String target = products[1];
        int n = Integer.parseInt(sc.nextLine().trim());
        List<String> using = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            using.add(sc.nextLine().trim());
        }
        int m = Integer.parseInt(sc.nextLine().trim());
        Set<String> supported = new HashSet<>();
        for (int i = 0; i < m; i++) {
            String[] row = sc.nextLine().trim().split("\\s+");
            if (row[0].equals(target)) {
                supported.add(row[1]);
            }
        }

        int ok = 0;
        for (String feature : using) {
            if (supported.contains(feature)) {
                ok++;
                System.out.println("OK " + feature);
            } else {
                System.out.println("NOT_SUPPORTED " + feature);
            }
        }
        System.out.println("移行できる " + ok + "/" + n);
        System.out.println("判定 " + (ok == n ? "そのまま移行可" : "代替が必要"));
    }
}
